const body = $input.first().json.body;
const required = ['feedback_items', 'product_area'];
const missing = required.filter(f => !body[f]);
if (missing.length) return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
if (!Array.isArray(body.feedback_items) || body.feedback_items.length < 3) return [{ json: { valid: false, error: 'feedback_items must be an array with at least 3 items' } }];
const items = body.feedback_items.map((item, i) => ({
  id: `F${String(i+1).padStart(3,'0')}`,
  text: (typeof item === 'string' ? item : item.text || '').trim().slice(0, 500),
  source: typeof item === 'object' ? (item.source || '') : '',
  rating: typeof item === 'object' && item.rating ? parseFloat(item.rating) : null,
  date: typeof item === 'object' ? (item.date || '') : '',
  user_tier: typeof item === 'object' ? (item.user_tier || '') : ''
})).filter(f => f.text.length > 10);
if (items.length < 3) return [{ json: { valid: false, error: 'Need at least 3 feedback items with meaningful text' } }];
const avgRating = items.filter(i => i.rating !== null).length > 0
  ? parseFloat((items.filter(i => i.rating !== null).reduce((s,i) => s + i.rating, 0) / items.filter(i => i.rating !== null).length).toFixed(1))
  : null;
return [{ json: {
  valid: true,
  productArea: body.product_area.trim(),
  feedbackPeriod: body.feedback_period || '',
  feedbackItems: items,
  totalCount: items.length,
  avgRating,
  audience: body.audience || 'product_team',
  productContext: (body.product_context || '').slice(0, 400),
  knownIssues: Array.isArray(body.known_issues) ? body.known_issues : (body.known_issues||'').split('\n').map(s=>s.trim()).filter(Boolean),
  replyEmail: body.reply_email || null
} }];

